import itertools
def periodic(inp, hid):
    H,W=len(inp),len(inp[0])
    # check if remaining cells are consistent with translation-invariance under several shifts
    ok=True
    shifts=[]
    for dx in range(-H,H):
        for dy in range(-W,W):
            if dx==0 and dy==0: continue
            bad=False
            for i in range(H):
                for j in range(W):
                    if inp[i][j] not in hid:
                        ii,jj=i+dx,j+dy
                        if 0<=ii<H and 0<=jj<W and inp[ii][jj] not in hid and inp[i][j]!=inp[ii][jj]:
                            bad=True
            if not bad: shifts.append((dx,dy))
    return shifts
