G=load()
def solve(g):
    H,W=len(g),len(g[0])
    cc=Counter(sum(g,[])); bg=cc.most_common(1)[0][0]
    # accent motif: connected component of non-bg cells; smallest bbox component
    seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                st=[(r,c)]; comp=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen or not(0<=a<H and 0<=b<W): continue
                    seen.add((a,b)); comp.append((a,b,g[a][b]))
                    for da,db in [(1,0),(-1,0),(0,1),(0,-1)]:
                        if 0<=a+da<H and 0<=b+db<W and g[a+da][b+db]!=bg and (a+da,b+db) not in seen: st.append((a+da,b+db))
                comps.append(comp)
    # motif = smallest comp (demo: 3 cells) ; others are distractors
    mot=min(comps,key=len)
    out=[row[:] for row in g]
    # stamp at every translation where all stamp cells either are bg-or-overlap-consistent
    valid=[]
    for dr in range(-H,H):
        for dc in range(-W,W):
            ok=True
            for r,c,v in mot:
                rr,cc=r+dr,c+dc
                if not(0<=rr<H and 0<=cc<W): ok=False;break
                if g[rr][cc]!=bg and out[rr][cc]!=v: ok=False;break
            if ok: valid.append((dr,dc))
    for dr,dc in valid:
        for r,c,v in mot:
            rr,cc=r+dr,c+dc
            out[rr][cc]=v
    return out
